"""Industry landing page content (4 of 4): immigration consultants and bookkeeping firms."""
from ind1 import I

I(demo="immigration-canada", url="immigration-consultants", name="Immigration & Visa Consultants", short="Immigration Consultant", singular="immigration consultancy",
  kf="licence display, a page for each programme, consultation booking and WhatsApp enquiries",
  intro="People searching for immigration help are anxious and comparing several consultants. They want to know three things fast: are you licensed, can you help with my programme and how do I speak to someone. A good immigration website answers all three without promising outcomes nobody can guarantee.",
  queries=["Express Entry consultant", "study permit consultant for Canada", "RCIC near me", "Super Visa application help", "work permit consultant online"],
  needs=[("Your licence, shown and verifiable", "Show the licence name and number on every page with a link to the regulator's public register. In Canada, immigration advice must come from a licensed professional, so this is your strongest trust signal."),
         ("One page for each programme", "Give Express Entry, study permits, work permits, visitor visas and sponsorship their own page, with who qualifies, the steps and the documents. Ads and search results then land on the right page."),
         ("Consultation booking", "A short form or calendar link, plus WhatsApp, so a visitor can book a call from any time zone."),
         ("Written fees and no guarantees", "State that fees are quoted in writing and that approval cannot be guaranteed. This builds trust and protects your licence."),
         ("A clear next step on every page", "A booking button in the header, the hero and the footer, and a reply-time promise you can keep."),
         ("FAQ in plain language", "Answer the questions people actually ask, such as what an RCIC does and whether you can consult from abroad. Marked-up FAQs help search engines and AI assistants quote you.")],
  mistakes=[("Promising approval or speed", "Words like 'guaranteed' or '100% approval' can breach professional rules and advertising policies. Describe your process and let clients judge."),
            ("One generic home page for every service", "A single banner repeated on every page does not tell visitors or Google what each page offers. Write a clear headline and a short summary for each programme."),
            ("Hiding the licence", "If visitors cannot find your licence number in seconds, they will go to a competitor who shows theirs.")],
  faq=[("How much does an immigration consultant website cost in Kerala?", "A single-page website with a consultation form and WhatsApp button starts at ₹5,000 with Qrenzy, and a complete six-section website with SEO and FAQ markup is typically ₹12,000. The first-year domain and hosting are included."),
       ("What should an immigration consultant's website include?", "It should show your licence and a link to the regulator's register, a page for each programme, a consultation booking form, written-fee wording and an FAQ. A WhatsApp button helps clients in many countries reach you quickly."),
       ("Can I advertise that I guarantee visa approval?", "No. Approval decisions are made by the immigration authorities, and guarantees can breach professional and advertising rules. Describe your services and your process instead. Check the rules that apply to you with your regulator."),
       ("Can clients book a consultation from abroad?", "Yes. A booking form or WhatsApp button lets visitors in any country ask for a video call, and you can reply in your own time zone.")],
  related=["legal", "travel", "accounting"])

I(demo="bookkeeping-us", url="bookkeeping-firms", name="Bookkeeping & Accounting Firms", short="Bookkeeping Firm", singular="bookkeeping firm",
  kf="service pages, clear pricing, a free intro call and client-type landing pages",
  intro="Business owners hire a bookkeeper when their books have fallen behind or when tax time scares them. They search for a specific kind of help, such as bookkeeping for contractors or catch-up for past months. A bookkeeping website should match those searches, show clear pricing and make a free intro call easy to book.",
  queries=["bookkeeping for small business", "bookkeeper for contractors", "e-commerce bookkeeping services", "QuickBooks cleanup service", "monthly bookkeeping near me"],
  needs=[("A page for each type of client", "Contractors, e-commerce sellers and small businesses search differently. A page for each, with their own examples and pricing, ranks and converts better than one general page."),
         ("Clear monthly pricing", "Show starting prices or packages. Visitors who cannot see a price often leave without asking."),
         ("Free intro call booking", "A short form or calendar link that books a 30-minute call, plus WhatsApp or email for people who prefer to write."),
         ("Software you support", "Name the tools you work in, such as QuickBooks Online and Xero, so owners know you fit their setup."),
         ("Honest scope", "Say clearly that you provide bookkeeping and not tax advice or filing unless you are qualified to. This protects you and sets the right expectations."),
         ("Security and process", "Explain how you access accounts, with read-only bank feeds where possible, and what clients receive each month.")],
  mistakes=[("Using protected titles loosely", "Titles such as CPA are reserved for people with the right credentials. Describe the service you actually offer."),
            ("Vague 'accounting services' wording", "Owners search for a specific problem, such as catch-up bookkeeping for past months. Name the problem on the page."),
            ("No clear next step", "Put a free intro call button in the header, the hero and the footer.")],
  faq=[("How much does a bookkeeping firm website cost in Kerala?", "A single-page website with a booking form and WhatsApp button starts at ₹5,000 with Qrenzy, and a complete six-section website with SEO and FAQ markup is typically ₹12,000. The first-year domain and hosting are included."),
       ("What should a bookkeeping website include?", "It should include your services, pricing or packages, the software you support, a page for each client type you serve, an FAQ and a free intro call button. Make clear whether you also offer tax services."),
       ("Can a bookkeeping firm in India serve overseas clients?", "Many firms do, but you should check the rules that apply to your services and to your clients' country, and agree scope, data security and fees in writing. Take advice from a qualified professional."),
       ("How do I get clients for a new bookkeeping business?", "Start with one client type, build a page for it with clear pricing and a free intro call, set up a Google Business Profile if you have a verifiable address and track every enquiry. Results depend on the market and cannot be guaranteed.")],
  related=["accounting", "finance-insurance", "corporate-b2b"])
